def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [{} for _ in range(w)]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                j = c - (c >= r)
                if j >= 0:
                    counts[j][v] = counts[j].get(v, 0) + 1

    seq = []
    for d in counts:
        seq.append(max(d, key=d.get) if d else None)

    # Find the repeating period of the underlying row pattern.
    period = None
    for p in range(1, min(10, w)):
        if all(v is None or seq[i % p] == v for i, v in enumerate(seq)):
            period = p
            break
    if period is None:
        period = min(9, w)

    pattern = seq[:period]
    return [[pattern[(c - (c >= r)) % period] for c in range(w)]
            for r in range(h)]
